        ob = new("/d/items/blade/jiedao2");
    else if (name == "chanzhang")
        ob = new("/d/items/staff/chanzhang2");
    else if (name == "changbian")
        ob = new("/d/items/whip/changbian2");
    else if (name == "qimeigun")
        ob = new("/d/items/club/qimei_gun");
    else
